import { ChangeEvent, FormEvent, useState } from 'react';
import { JxAlert, JxButton, JxInputField, JxStepper } from '@jinx-ui/react';

type RegistrationWizardData = {
  fullName: string;
  email: string;
  phone: string;
  city: string;
  street: string;
  postalCode: string;
};

type RegistrationWizardProps = {
  onSubmit: (data: RegistrationWizardData) => void;
};

const STEPS = [
  { label: 'Контакты' },
  { label: 'Адрес' },
  { label: 'Проверка' },
];

const REVIEW_ROWS: Array<{ label: string; field: keyof RegistrationWizardData }> = [
  { label: 'Имя и фамилия', field: 'fullName' },
  { label: 'Электронная почта', field: 'email' },
  { label: 'Телефон', field: 'phone' },
  { label: 'Город', field: 'city' },
  { label: 'Улица и дом', field: 'street' },
  { label: 'Почтовый индекс', field: 'postalCode' },
];

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationWizardData>({
    fullName: '',
    email: '',
    phone: '',
    city: '',
    street: '',
    postalCode: '',
  });

  const updateField = (field: keyof RegistrationWizardData) => (event: ChangeEvent<HTMLInputElement>) => {
    const nextValue = event.target.value;
    setData((previous) => ({ ...previous, [field]: nextValue }));
  };

  const isLastStep = step === STEPS.length - 1;
  const isStepValid =
    step === 0
      ? data.fullName.trim().length > 0 && data.email.trim().length > 0
      : step === 1
        ? data.city.trim().length > 0 && data.street.trim().length > 0
        : true;

  const handleBack = () => {
    setStep((current) => Math.max(current - 1, 0));
  };

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isStepValid) {
      return;
    }
    if (isLastStep) {
      onSubmit(data);
      return;
    }
    setStep((current) => Math.min(current + 1, STEPS.length - 1));
  };

  return (
    <form onSubmit={handleSubmit}>
      <JxStepper current={step} steps={STEPS} />
      <div style={{ display: 'flex', flexDirection: 'column', gap: '16px', marginTop: '24px' }}>
        {step === 0 && (
          <>
            <JxInputField
              label="Имя и фамилия"
              name="fullName"
              autoComplete="name"
              required
              value={data.fullName}
              onChange={updateField('fullName')}
            />
            <JxInputField
              label="Электронная почта"
              name="email"
              type="email"
              autoComplete="email"
              required
              value={data.email}
              onChange={updateField('email')}
            />
            <JxInputField
              label="Телефон"
              name="phone"
              type="tel"
              autoComplete="tel"
              prefix="+7"
              value={data.phone}
              onChange={updateField('phone')}
            />
          </>
        )}
        {step === 1 && (
          <>
            <JxInputField
              label="Город"
              name="city"
              autoComplete="address-level2"
              required
              value={data.city}
              onChange={updateField('city')}
            />
            <JxInputField
              label="Улица и дом"
              name="street"
              autoComplete="street-address"
              required
              value={data.street}
              onChange={updateField('street')}
            />
            <JxInputField
              label="Почтовый индекс"
              name="postalCode"
              autoComplete="postal-code"
              value={data.postalCode}
              onChange={updateField('postalCode')}
            />
          </>
        )}
        {step === 2 && (
          <>
            <JxAlert intent="info" title="Проверьте данные перед отправкой">
              Если нужно что-то исправить, вернитесь на предыдущий шаг.
            </JxAlert>
            <div style={{ display: 'grid', gridTemplateColumns: 'auto 1fr', gap: '8px 16px' }}>
              {REVIEW_ROWS.map((row) => (
                <div key={row.field} style={{ display: 'contents' }}>
                  <span>{row.label}</span>
                  <span>{data[row.field]}</span>
                </div>
              ))}
            </div>
          </>
        )}
      </div>
      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '12px', marginTop: '24px' }}>
        <JxButton type="button" variant="ghost" onClick={handleBack} disabled={step === 0}>
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary" disabled={!isStepValid}>
          {isLastStep ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

